void HandleResourceReception(std::vector<GURL>& resources_list, std::vector<Referrer>& referrers_list, std::vector<GURL>& frames_list) {
    if (!IsInCorrectWaitState()) {
        return;
    }

    int total_items = resources_list.size() + frames_list.size();
    if (IsDownloadInProgress()) {
        UpdateDownloadTotalBytes(total_items * AVERAGE_RESOURCE_SIZE);
    }

    bool has_valid_urls = false;
    for (size_t i = 0; i < resources_list.size(); ++i) {
        GURL url = resources_list[i];
        if (url.is_valid()) {
            SaveItem item = CreateSaveItem(url, referrers_list[i]);
            AddToWaitingQueue(item);
            has_valid_urls = true;
        }
    }

    for (GURL frame_url : frames_list) {
        if (frame_url.is_valid()) {
            SaveItem item = CreateSaveItem(frame_url, Referrer());
            AddToWaitingQueue(item);
            has_valid_urls = true;
        }
    }

    if (!has_valid_urls) {
        HandleUserCancellation();
        return;
    }

    UpdateWaitState();
    StartSavingProcess();
}

void HandleReceivingResourceLinks(std::vector<GURL>& resources_list,
                                  std::vector<Referrer>& referrers_list,
                                  std::vector<GURL>& frames_list) {
  if (!IsInCorrectWaitState()) {
    return;
  }

  size_t total_items_to_save = resources_list.size() + frames_list.size();
  if (download_in_progress) {
    download->UpdateTotalBytes(total_items_to_save);
  }

  if (total_items_to_save == 0) {
    HandleUserCancellation();
    return;
  }

  for (size_t i = 0; i < resources_list.size(); ++i) {
    const GURL& resource = resources_list[i];
    const Referrer& referrer = referrers_list[i];
    if (resource.is_valid()) {
      SaveItem item = CreateSaveItem(resource, referrer);
      waiting_queue.push_back(item);
    }
  }

  for (const GURL& frame : frames_list) {
    if (frame.is_valid()) {
      SaveItem item = CreateSaveItem(frame, Referrer());
      waiting_queue.push_back(item);
    }
  }

  UpdateWaitState();
  InitiateSaveProcess();
}

void HandleSaveResourceLinks(std::vector<GURL>& resources_list, std::vector<Referrer>& referrers_list, std::vector<GURL>& frames_list) {
    if (!IsInCorrectWaitState()) {
        return;
    }

    size_t total_items = resources_list.size() + frames_list.size();
    if (download_in_progress) {
        download->UpdateTotalBytes(total_items * average_item_size);
    }

    if (resources_list.size() != referrers_list.size()) {
        return;
    }

    for (size_t i = 0; i < resources_list.size(); ++i) {
        const GURL& resource_url = resources_list[i];
        const Referrer& referrer = referrers_list[i];
        if (resource_url.is_valid()) {
            SaveItem item(resource_url, referrer);
            waiting_queue.push_back(item);
        }
    }

    for (const GURL& frame_url : frames_list) {
        if (frame_url.is_valid()) {
            SaveItem item(frame_url, Referrer());
            waiting_queue.push_back(item);
        }
    }

    if (waiting_queue.empty()) {
        HandleUserCancellation();
        return;
    }

    UpdateWaitState(SAVE_IN_PROGRESS);
    StartSavingProcess();
}

void handle_received_savable_resource_links(std::vector<GURL>& resources_list, std::vector<Referrer>& referrers_list, std::vector<GURL>& frames_list) {
    if (!is_in_wait_state(WAIT_STATE_RECEIVING_LINKS)) {
        return;
    }

    int total_items = 0;
    for (const auto& url : resources_list) {
        if (url.is_valid())
            total_items++;
    }
    for (const auto& url : frames_list) {
        if (url.is_valid())
            total_items++;
    }

    if (download_in_progress) {
        download.total_bytes += total_items * AVERAGE_RESOURCE_SIZE;
    }

    for (size_t i = 0; i < resources_list.size(); ++i) {
        GURL resource_url = resources_list[i];
        if (resource_url.is_valid()) {
            Referrer referrer = referrers_list[i];
            SaveItem* item = create_save_item(resource_url, referrer);
            add_to_waiting_queue(item);
        }
    }

    for (const auto& frame_url : frames_list) {
        if (frame_url.is_valid()) {
            SaveItem* item = create_save_item(frame_url, Referrer());
            add_to_waiting_queue(item);
        }
    }

    if (get_waiting_queue_size() == 0) {
        handle_user_cancellation();
    }

    update_wait_state(WAIT_STATE_SAVING);
    start_saving_process();
}

void handle_reception_of_savable_resource_links(std::vector<GURL>& resources_list, std::vector<Referrer>& referrers_list, std::vector<GURL>& frames_list) {
    if (!is_in_correct_wait_state()) {
        return;
    }

    size_t total_items_to_save = resources_list.size() + frames_list.size();
    if (download_in_progress) {
        download->total_bytes += total_items_to_save * AVERAGE_RESOURCE_SIZE;
    }

    for (size_t i = 0; i < resources_list.size(); ++i) {
        GURL url = resources_list[i];
        if (!url.is_valid()) {
            continue;
        }
        SaveItem item;
        item.url = url;
        item.referrer = referrers_list[i];
        waiting_queue.push(item);
    }

    for (size_t i = 0; i < frames_list.size(); ++i) {
        GURL url = frames_list[i];
        if (!url.is_valid()) {
            continue;
        }
        SaveItem item;
        item.url = url;
        waiting_queue.push(item);
    }

    if (waiting_queue.empty()) {
        handle_user_cancellation();
    }

    update_wait_state();
    initiate_saving_process();
}
